public class TryCatchFlow {
    static String test() {
        String res = "";
        try {
            res += "T";
            throw new Exception();
        } catch (Exception e) {
            res += "C";
            return res;
        } finally {
            res += "F";
        }
    }
    public static void main(String[] args) {
        System.out.println(test());
    }
}

